<?php
/** Presentation for the agent workspace; operational decisions live in its read model. */
if ( ! defined( 'ABSPATH' ) ) { exit; }
class Olama_Messages_Agent_Page {
    private static function url( $page, $id = 0 ) { return admin_url( 'admin.php?page=' . $page . ( $id ? '&campaign_id=' . (int) $id : '' ) ); }
    private static function time( $value, $utc = true ) {
        $stamp = $utc ? Olama_Messages_Agent_Dashboard::utc_timestamp( $value ) : 0;
        return '<time title="' . esc_attr( Olama_Messages_Agent_Dashboard::time_label( $value, $utc ) ) . '">' . esc_html( $stamp ? wp_date( 'H:i:s', $stamp ) : Olama_Messages_Agent_Dashboard::time_label( $value, $utc ) ) . '</time>';
    }
    public static function part( $name, $data ) { ob_start(); self::$name( $data ); return ob_get_clean(); }
    public static function hero( $d ) {
        $a = $d['agent']; $h = $d['health']; ?>
        <section class="om-agent-hero" data-tone="<?php echo esc_attr( $h['tone'] ); ?>">
            <div class="om-agent-hero-main"><span class="om-agent-eyebrow"><?php esc_html_e( 'SENDING WORKER', 'olama-messages' ); ?></span>
                <h2><span class="om-agent-status-dot"></span><?php echo esc_html( $h['label'] ); ?></h2>
                <p><?php echo esc_html( $h['description'] ); ?></p>
                <div class="om-agent-connections"><span><span class="dashicons dashicons-desktop"></span><?php echo esc_html( $a['machine_name'] ?: __( 'Computer not reported', 'olama-messages' ) ); ?></span>
                    <span><span class="dashicons dashicons-smartphone"></span><?php echo esc_html( $a['kde_device_name'] ?: __( 'No phone selected', 'olama-messages' ) ); ?></span>
                    <span><?php echo esc_html( sprintf( __( 'Agent v%s', 'olama-messages' ), $a['app_version'] ?: '—' ) ); ?></span></div>
            </div>
            <div class="om-agent-heartbeat"><span class="om-agent-eyebrow"><?php esc_html_e( 'LAST HEARTBEAT', 'olama-messages' ); ?></span>
                <strong><?php echo esc_html( Olama_Messages_Agent_Dashboard::age_label( Olama_Messages_Agent_Dashboard::utc_timestamp( $a['last_seen_at'] ) ) ); ?></strong>
                <small><?php echo esc_html( Olama_Messages_Agent_Dashboard::time_label( $a['last_seen_at'] ) ); ?> · <?php echo esc_html( wp_timezone_string() ); ?></small>
                <span class="om-agent-hero-note"><?php esc_html_e( 'Activity below updates independently', 'olama-messages' ); ?></span>
            </div>
        </section><?php
    }
    public static function metrics( $d ) { ?>
        <div class="om-agent-metrics">
            <article><span><?php esc_html_e( 'Target cadence', 'olama-messages' ); ?></span><strong><?php echo (int) $d['target']; ?><small> sec</small></strong><p><?php echo esc_html( $d['median'] !== null ? sprintf( __( '%s sec observed · recent median', 'olama-messages' ), number_format_i18n( $d['median'], 1 ) ) : __( 'Server policy · waiting for samples', 'olama-messages' ) ); ?></p></article>
            <article><span><?php esc_html_e( 'Last submission', 'olama-messages' ); ?></span><strong class="om-agent-time-value"><?php echo self::time( $d['last_sent'] ); ?></strong><p><?php echo esc_html( Olama_Messages_Agent_Dashboard::age_label( Olama_Messages_Agent_Dashboard::utc_timestamp( $d['last_sent'] ) ) ); ?></p></article>
            <article><span><?php esc_html_e( 'Remaining in campaign', 'olama-messages' ); ?></span><strong><?php echo number_format_i18n( $d['pending'] + $d['counts']['reserved'] ); ?></strong><p><?php esc_html_e( 'Queued or in progress', 'olama-messages' ); ?></p></article>
            <article class="<?php echo $d['review'] ? 'om-agent-metric-alert' : ''; ?>"><span><?php esc_html_e( 'Need review', 'olama-messages' ); ?></span><strong><?php echo number_format_i18n( $d['review'] ); ?></strong><p><?php echo esc_html( $d['review'] ? __( 'Check phone history before retrying', 'olama-messages' ) : __( 'No uncertain outcomes for this agent', 'olama-messages' ) ); ?></p></article>
        </div><?php
    }
    public static function campaign( $d ) {
        $c = $d['campaign']; $counts = $d['counts']; $total = array_sum( $counts ); $pct = $total ? round( $counts['sent'] / $total * 100 ) : 0; ?>
        <section class="om-agent-panel om-agent-campaign"><div class="om-agent-panel-heading"><div><span class="om-agent-eyebrow"><?php esc_html_e( 'CAMPAIGN ACTIVITY', 'olama-messages' ); ?></span><h2><?php echo esc_html( $c ? $c['title'] : __( 'Ready for your next campaign', 'olama-messages' ) ); ?></h2></div>
            <?php if ( $c ) : ?><a class="om-agent-link" href="<?php echo esc_url( self::url( 'olama-messages-campaign-progress', $c['id'] ) ); ?>"><?php esc_html_e( 'Open campaign', 'olama-messages' ); ?> <span aria-hidden="true">↗</span></a><?php endif; ?></div>
        <?php if ( $c ) : ?>
            <div class="om-agent-campaign-stats"><span><strong><?php echo number_format_i18n( $counts['sent'] ); ?></strong> <?php esc_html_e( 'submitted via KDE', 'olama-messages' ); ?></span><span><?php echo esc_html( ucwords( str_replace( '_', ' ', $c['status'] ) ) ); ?></span></div>
            <div class="om-agent-progress" role="progressbar" aria-label="<?php esc_attr_e( 'Campaign submissions', 'olama-messages' ); ?>" aria-valuenow="<?php echo (int) $pct; ?>" aria-valuemin="0" aria-valuemax="100"><span style="width:<?php echo (int) $pct; ?>%"></span></div>
            <div class="om-agent-campaign-foot"><span><?php echo (int) $pct; ?>% <?php esc_html_e( 'submitted', 'olama-messages' ); ?> · <?php echo number_format_i18n( $counts['failed'] ); ?> <?php esc_html_e( 'failed', 'olama-messages' ); ?> · <?php echo number_format_i18n( $counts['unknown'] ); ?> <?php esc_html_e( 'need review', 'olama-messages' ); ?></span>
                <span><?php echo esc_html( $d['active'] ? sprintf( __( 'Working on message #%d', 'olama-messages' ), $d['active']['id'] ) : __( 'No message currently reserved', 'olama-messages' ) ); ?></span></div>
        <?php else : ?><p class="om-agent-muted"><?php esc_html_e( 'This agent has not claimed a campaign yet. Prepare and authorize a campaign to begin.', 'olama-messages' ); ?></p><?php endif; ?>
        <?php if ( $d['review'] ) : ?><div class="om-agent-callout"><span class="dashicons dashicons-warning"></span><span><?php esc_html_e( 'Uncertain outcomes are held safely. Open Delivery Operations to find and review them.', 'olama-messages' ); ?> <a href="<?php echo esc_url( self::url( 'olama-messages-delivery' ) ); ?>"><?php esc_html_e( 'Review outcomes', 'olama-messages' ); ?></a></span></div><?php endif; ?>
        <p class="om-agent-disclaimer"><?php esc_html_e( 'Submitted via KDE means the command completed. Recipient delivery is not confirmed.', 'olama-messages' ); ?></p></section><?php
    }
    public static function activity( $d ) {
        $labels = array( 'reserved' => __( 'In progress', 'olama-messages' ), 'sent' => __( 'Submitted via KDE', 'olama-messages' ), 'unknown' => __( 'Review needed', 'olama-messages' ), 'retry_wait' => __( 'Retry scheduled', 'olama-messages' ), 'failed' => __( 'Failed', 'olama-messages' ), 'reviewed' => __( 'Reviewed', 'olama-messages' ) );
        if ( ! $d['attempts'] ) { echo '<div class="om-agent-empty"><span class="dashicons dashicons-email-alt"></span><h3>' . esc_html__( 'Activity will appear here', 'olama-messages' ) . '</h3><p>' . esc_html__( 'Each send attempt appears once, with its latest outcome.', 'olama-messages' ) . '</p></div>'; return; } ?>
        <div class="om-agent-table-scroll"><table class="om-agent-activity-table"><thead><tr><th><?php esc_html_e( 'Time', 'olama-messages' ); ?></th><th><?php esc_html_e( 'Message', 'olama-messages' ); ?></th><th><?php esc_html_e( 'Outcome', 'olama-messages' ); ?></th><th><?php esc_html_e( 'Details', 'olama-messages' ); ?></th></tr></thead><tbody>
        <?php foreach ( $d['attempts'] as $row ) : $problem = in_array( $row['status'], array( 'failed','unknown','retry_wait' ), true ); $phone = $row['phone_e164'] ? substr( $row['phone_e164'], 0, 5 ) . '•••' . substr( $row['phone_e164'], -3 ) : '—'; ?>
            <tr data-problem="<?php echo $problem ? '1' : '0'; ?>"><td><?php echo self::time( $row['created_at'] ); ?><small><?php echo esc_html( Olama_Messages_Agent_Dashboard::age_label( Olama_Messages_Agent_Dashboard::utc_timestamp( $row['created_at'] ) ) ); ?></small></td>
                <td><strong><?php echo esc_html( $row['recipient_name'] ?: sprintf( __( 'Message #%d', 'olama-messages' ), $row['queue_id'] ) ); ?></strong><small><bdi><?php echo esc_html( $phone ); ?></bdi> <span aria-hidden="true">·</span> <?php echo esc_html( $row['campaign_title'] ?: __( 'Historical campaign', 'olama-messages' ) ); ?></small></td>
                <td><span class="om-agent-badge" data-tone="<?php echo esc_attr( $problem ? 'warning' : ( 'sent' === $row['status'] ? 'success' : 'muted' ) ); ?>"><?php echo esc_html( $labels[$row['status']] ?? $row['status'] ); ?></span></td>
                <td><details data-attempt="<?php echo esc_attr( $row['attempt_id'] ); ?>"><summary><?php esc_html_e( 'Inspect', 'olama-messages' ); ?></summary><dl><dt><?php esc_html_e( 'Message', 'olama-messages' ); ?></dt><dd>#<?php echo (int) $row['queue_id']; ?></dd><dt><?php esc_html_e( 'Attempt ID', 'olama-messages' ); ?></dt><dd><code><?php echo esc_html( $row['attempt_id'] ); ?></code></dd><dt><?php esc_html_e( 'Result recorded', 'olama-messages' ); ?></dt><dd><?php echo esc_html( Olama_Messages_Agent_Dashboard::time_label( $row['updated_at'] ) ); ?></dd>
                    <?php if ( $problem && $row['dispatch_attempt_id'] === $row['attempt_id'] && $row['last_error_message'] ) : ?><dt><?php esc_html_e( 'Reason', 'olama-messages' ); ?></dt><dd><?php echo esc_html( $row['last_error_message'] ); ?></dd><?php endif; ?></dl></details></td></tr>
        <?php endforeach; ?></tbody></table></div><?php
    }
    private static function configuration( $d ) {
        $a = $d['agent']; $values = array( __( 'Agent ID', 'olama-messages' ) => $a['agent_uuid'], __( 'Computer / user', 'olama-messages' ) => $a['machine_name'] . ' / ' . $a['windows_user'], __( 'Platform / version', 'olama-messages' ) => $a['platform'] . ' / ' . $a['app_version'], __( 'KDE CLI path', 'olama-messages' ) => $a['kde_cli_path'], __( 'Phone ID', 'olama-messages' ) => $a['kde_device_id'], __( 'Registered', 'olama-messages' ) => Olama_Messages_Agent_Dashboard::time_label( $a['created_at'], false ), __( 'Last worker poll', 'olama-messages' ) => Olama_Messages_Agent_Dashboard::time_label( $d['last_poll'] ), __( 'Reported worker state', 'olama-messages' ) => $d['worker_state'], __( 'Last reported error', 'olama-messages' ) => $d['last_error'] ?: __( 'None reported', 'olama-messages' ) ); ?>
        <details class="om-agent-panel om-agent-disclosure"><summary><span><strong><?php esc_html_e( 'Configuration & diagnostics', 'olama-messages' ); ?></strong><small><?php esc_html_e( 'Computer, version, identifiers and connection details', 'olama-messages' ); ?></small></span><span class="dashicons dashicons-arrow-down-alt2"></span></summary><dl class="om-agent-config-grid">
            <?php foreach ( $values as $label => $value ) : ?><div><dt><?php echo esc_html( $label ); ?></dt><dd><?php echo esc_html( $value ?: '—' ); ?></dd></div><?php endforeach; ?>
        </dl><p class="om-agent-muted"><?php esc_html_e( 'Configuration and diagnostic values are captured at page load. The regular heartbeat reports phone connectivity; live message outcomes come directly from the dispatch queue.', 'olama-messages' ); ?></p></details><?php
    }
    private static function administration( $d ) {
        $id = (int) $d['agent']['id']; ?>
        <details class="om-agent-administration"><summary><?php esc_html_e( 'Administrative actions', 'olama-messages' ); ?></summary><p><?php esc_html_e( 'Revoking access stops authentication. Deleting removes the registration while preserving delivery history.', 'olama-messages' ); ?></p>
        <?php if ( 'revoked' !== $d['agent']['status'] ) : ?><a class="button" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=olama_msg_revoke_agent&agent_id=' . $id ), 'olama_msg_revoke_agent_' . $id ) ); ?>" onclick="return confirm('<?php esc_attr_e( 'Revoke this agent and stop its authentication?', 'olama-messages' ); ?>');"><?php esc_html_e( 'Revoke access', 'olama-messages' ); ?></a><?php endif; ?>
        <a class="button button-link-delete" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=olama_msg_delete_agent&agent_id=' . $id ), 'olama_msg_delete_agent_' . $id ) ); ?>" onclick="return confirm('<?php esc_attr_e( 'Permanently delete this agent registration? This cannot be undone.', 'olama-messages' ); ?>');"><?php esc_html_e( 'Delete registration', 'olama-messages' ); ?></a></details><?php
    }
    public static function detail( $d ) { ?>
        <div class="wrap om-agent" id="om-agent-workspace" data-agent-id="<?php echo (int) $d['agent']['id']; ?>">
            <a class="om-agent-back" href="<?php echo esc_url( self::url( 'olama-messages-agents' ) ); ?>">← <?php esc_html_e( 'All sending agents', 'olama-messages' ); ?></a>
            <header class="om-agent-page-heading"><div><p class="om-agent-eyebrow"><?php esc_html_e( 'DELIVERY WORKSPACE', 'olama-messages' ); ?></p><h1><?php echo esc_html( $d['agent']['agent_name'] ); ?><span class="om-agent-heading-device"><?php echo esc_html( $d['agent']['kde_device_name'] ?: __( 'Sending agent', 'olama-messages' ) ); ?></span></h1></div><div class="om-agent-sync"><span data-sync-label role="status"><?php esc_html_e( 'Live · refreshes every 5 seconds', 'olama-messages' ); ?></span><button type="button" class="button" data-agent-refresh><?php esc_html_e( 'Refresh', 'olama-messages' ); ?></button></div></header>
            <?php foreach ( array( 'hero','metrics','campaign' ) as $part ) : ?><div data-agent-part="<?php echo esc_attr( $part ); ?>"><?php echo self::part( $part, $d ); ?></div><?php endforeach; ?>
            <section class="om-agent-panel om-agent-activity"><div class="om-agent-panel-heading"><div><h2><?php esc_html_e( 'Recent activity', 'olama-messages' ); ?></h2><p><?php esc_html_e( 'One row per attempt. Latest 50 attempts for this agent.', 'olama-messages' ); ?></p></div><label class="om-agent-filter"><?php esc_html_e( 'Show', 'olama-messages' ); ?> <select data-agent-filter><option value="all"><?php esc_html_e( 'All outcomes', 'olama-messages' ); ?></option><option value="problems"><?php esc_html_e( 'Needs attention', 'olama-messages' ); ?></option></select></label></div><div data-agent-part="activity"><?php echo self::part( 'activity', $d ); ?></div><div class="om-agent-pagination" data-agent-pagination><span data-agent-page-label></span><div><button type="button" class="button" data-agent-prev>Previous</button><button type="button" class="button" data-agent-next>Next</button></div></div><p class="om-agent-filter-empty" hidden><?php esc_html_e( 'No issues in the recent attempts.', 'olama-messages' ); ?></p></section>
            <?php self::configuration( $d ); ?>
            <details class="om-agent-panel om-agent-disclosure"><summary><span><strong><?php esc_html_e( 'Technical audit', 'olama-messages' ); ?></strong><small><?php esc_html_e( 'Latest 20 events at page load · diagnostics and support', 'olama-messages' ); ?></small></span><span class="dashicons dashicons-arrow-down-alt2"></span></summary><div class="om-agent-audit"><?php foreach ( $d['events'] as $event ) : ?><article><time><?php echo esc_html( Olama_Messages_Agent_Dashboard::time_label( $event['created_at'], false ) ); ?></time><strong><?php echo esc_html( $event['event_type'] ); ?></strong><p><?php echo esc_html( $event['message'] ); ?></p><details><summary><?php esc_html_e( 'Event data', 'olama-messages' ); ?></summary><pre><?php echo esc_html( $event['context_json'] ); ?></pre></details></article><?php endforeach; ?></div></details>
            <?php self::administration( $d ); ?>
        </div><?php
    }
    public static function fleet( $agents ) { ?>
        <div class="om-agent-fleet"><?php foreach ( $agents as $d ) : ?><article class="om-agent-fleet-card"><div class="om-agent-fleet-heading"><div class="om-agent-device-icon"><span class="dashicons dashicons-desktop"></span></div><div><h2><a href="<?php echo esc_url( admin_url( 'admin.php?page=olama-messages-agents&action=view&agent_id=' . $d['agent']['id'] ) ); ?>"><?php echo esc_html( $d['agent']['agent_name'] ); ?></a></h2><p><?php echo esc_html( $d['agent']['machine_name'] ?: __( 'Awaiting first heartbeat', 'olama-messages' ) ); ?></p></div><span class="om-agent-badge" data-tone="<?php echo esc_attr( $d['health']['tone'] ); ?>"><?php echo esc_html( $d['health']['label'] ); ?></span></div><p class="om-agent-fleet-description"><?php echo esc_html( $d['health']['description'] ); ?></p><div class="om-agent-fleet-phone"><span class="dashicons dashicons-smartphone"></span><strong><?php echo esc_html( $d['agent']['kde_device_name'] ?: __( 'Phone not reported', 'olama-messages' ) ); ?></strong><span><?php echo esc_html( $d['agent']['kde_device_reachable'] ? ( in_array( $d['health']['key'], array( 'offline','revoked' ), true ) ? __( 'Last reported connected', 'olama-messages' ) : __( 'Connected', 'olama-messages' ) ) : __( 'Not connected', 'olama-messages' ) ); ?></span></div><footer><span><?php echo esc_html( Olama_Messages_Agent_Dashboard::age_label( Olama_Messages_Agent_Dashboard::utc_timestamp( $d['agent']['last_seen_at'] ) ) ); ?></span><a class="om-agent-link" href="<?php echo esc_url( admin_url( 'admin.php?page=olama-messages-agents&action=view&agent_id=' . $d['agent']['id'] ) ); ?>"><?php esc_html_e( 'Open workspace', 'olama-messages' ); ?> ↗</a></footer></article><?php endforeach; ?></div>
        <?php if ( ! $agents ) : ?><div class="om-agent-panel om-agent-empty"><span class="dashicons dashicons-desktop"></span><h2><?php esc_html_e( 'Connect your first sending computer', 'olama-messages' ); ?></h2><p><?php esc_html_e( 'Register an agent, then enter its credentials in the Windows app.', 'olama-messages' ); ?></p></div><?php endif; ?>
    <?php }
    public static function listing( $agents ) { ?>
        <div class="wrap om-agent" id="om-agent-list" data-agent-id="0"><header class="om-agent-page-heading"><div><p class="om-agent-eyebrow"><?php esc_html_e( 'DELIVERY WORKSPACE', 'olama-messages' ); ?></p><h1><?php esc_html_e( 'Sending agents', 'olama-messages' ); ?></h1><p><?php esc_html_e( 'Your sending computers, connected phones and worker health in one place.', 'olama-messages' ); ?></p></div><div class="om-agent-fleet-tools"><a class="button button-primary" href="#om-agent-register" data-agent-add><?php esc_html_e( '+ Add agent', 'olama-messages' ); ?></a><div class="om-agent-sync"><span data-sync-label role="status"><?php esc_html_e( 'Live · refreshes every 15 seconds', 'olama-messages' ); ?></span><button type="button" class="button" data-agent-refresh><?php esc_html_e( 'Refresh', 'olama-messages' ); ?></button></div></div></header>
        <div data-agent-part="fleet"><?php self::fleet( $agents ); ?></div>
        <details class="om-agent-panel om-agent-disclosure" id="om-agent-register" <?php echo ! $agents ? 'open' : ''; ?>><summary><span><strong><?php esc_html_e( 'Register a sending agent', 'olama-messages' ); ?></strong><small><?php esc_html_e( 'Add another computer and paired phone', 'olama-messages' ); ?></small></span><span class="dashicons dashicons-plus-alt2"></span></summary><form class="om-agent-register-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'olama_msg_save_agent' ); ?><input type="hidden" name="action" value="olama_msg_save_agent"><label for="agent_name"><?php esc_html_e( 'Agent name', 'olama-messages' ); ?></label><div><input id="agent_name" name="agent_name" type="text" placeholder="<?php esc_attr_e( 'e.g. School office', 'olama-messages' ); ?>" required maxlength="190"><button class="button button-primary"><?php esc_html_e( 'Register agent', 'olama-messages' ); ?></button></div><p><?php esc_html_e( 'Use a familiar name so your team can identify this computer.', 'olama-messages' ); ?></p></form></details></div><?php
    }
}
